     1	package br.com.loja.shipping;
     2	
     3	import java.math.BigDecimal;
     4	import java.util.Optional;
     5	
     6	import br.com.loja.common.Money;
     7	
     8	/** Região do cliente: seguro cobrado pela seguradora e atraso de despacho das transportadoras. */
     9	public enum Region {
    10	    SOUTHEAST("0.01", null, 0),
    11	    SOUTH("0.01", null, 0),
    12	    MIDWEST("0.015", null, 0),
    13	    NORTH("0.025", "30.00", 3),
    14	    NORTHEAST("0.02", "30.00", 2);
    15	
    16	    private final String insuranceRate;
    17	    private final BigDecimal insuranceLimit;
    18	    private final int carrierExtraDays;
    19	
    20	    Region(String insuranceRate, String insuranceLimit, int carrierExtraDays) {
    21	        this.insuranceRate = insuranceRate;
    22	        this.insuranceLimit = insuranceLimit == null ? null : Money.of(insuranceLimit);
    23	        this.carrierExtraDays = carrierExtraDays;
    24	    }
    25	
    26	    public BigDecimal insuranceFor(BigDecimal productsSubtotal) {
    27	        BigDecimal insurance = Money.percent(productsSubtotal, insuranceRate);
    28	        return insuranceLimit != null ? insurance.min(insuranceLimit) : insurance;
    29	    }
    30	
    31	    public int carrierExtraDays() {
    32	        return carrierExtraDays;
    33	    }
    34	
    35	    public static Optional<Region> parse(String code) {
    36	        for (Region region : values()) {
    37	            if (region.name().equals(code)) {
    38	                return Optional.of(region);
    39	            }
    40	        }
    41	        return Optional.empty();
    42	    }
    43	}
