=== shipping/TransLogGateway.java
     1	package br.com.loja.shipping;
     2	
     3	import java.math.BigDecimal;
     4	import java.net.URI;
     5	import java.net.http.HttpClient;
     6	import java.net.http.HttpRequest;
     7	import java.net.http.HttpResponse;
     8	import java.time.Duration;
     9	
    10	import org.springframework.beans.factory.annotation.Value;
    11	import org.springframework.stereotype.Component;
    12	
    13	import tools.jackson.databind.JsonNode;
    14	import tools.jackson.databind.json.JsonMapper;
    15	
    16	@Component
    17	public class TransLogGateway implements CarrierGateway {
    18	
    19	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
    20	
    21	    private final String baseUrl;
    22	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
    23	    private final JsonMapper json = JsonMapper.builder().build();
    24	
    25	    public TransLogGateway(@Value("${translog.url:}") String baseUrl) {
    26	        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    27	    }
    28	
    29	    @Override
    30	    public CarrierQuote quote(String zipCode, long weightGrams, String service) {
    31	        JsonNode body;
    32	        try {
    33	            HttpRequest request = HttpRequest.newBuilder(URI.create(
    34	                            baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams + "&service="
    35	                                    + (service.equals("STD") ? "STD" : "EXP")))
    36	                    .timeout(TIMEOUT).GET().build();
    37	            HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
    38	            if (response.statusCode() != 200) {
    39	                throw new CarrierDownException("TransLog respondeu " + response.statusCode(), null);
    40	            }
    41	            body = json.readTree(response.body());
    42	        } catch (InterruptedException e) {
    43	            Thread.currentThread().interrupt();
    44	            throw new CarrierDownException("Consulta à TransLog interrompida", e);
    45	        } catch (CarrierDownException e) {
    46	            throw e;
    47	        } catch (Exception e) {
    48	            throw new CarrierDownException("Falha ao consultar a TransLog", e);
    49	        }
    50	        if (body.has("error")) {
    51	            if ("ZIP_NOT_SERVED".equals(body.get("error").asString())) {
    52	                throw new ZipNotServedException();
    53	            }
    54	            throw new CarrierDownException("TransLog respondeu erro " + body.get("error"), null);
    55	        }
    56	        JsonNode cents = body.get("price_cents");
    57	        JsonNode hours = body.get("eta_hours");
    58	        if (cents == null || hours == null || !cents.isIntegralNumber() || !hours.isIntegralNumber()
    59	                || hours.longValue() < 0) {
    60	            throw new CarrierDownException("Resposta inesperada da TransLog", null);
    61	        }
    62	        BigDecimal price = BigDecimal.valueOf(cents.longValue(), 2);
    63	        int days = (int) ((hours.longValue() + 23) / 24);
    64	        return new CarrierQuote(price, days);
    65	    }
    66	}

