    31	/** Calcula o resumo da compra. É a única fonte dos valores, tanto do resumo quanto do pedido registrado. */
    32	@Service
    33	public class CheckoutService {
    34	
    35	    private static final String COUPON_CAP_RATE = "0.30";
    36	
    37	    private final ProductRepository products;
    38	    private final OrderRepository orders;
