    44	    CheckoutService(ProductRepository products, OrderRepository orders, List<ShippingOption> shippingOptions,
    45	                    List<Coupon> coupons, List<ClubTier> tiers, List<PaymentOption> paymentOptions) {
    46	        this.products = products;
    47	        this.orders = orders;
    48	        this.shippingOptions = index(shippingOptions, ShippingOption::code);
    49	        this.coupons = index(coupons, Coupon::code);
    50	        this.tiers = index(tiers, ClubTier::code);
    51	        this.paymentOptions = index(paymentOptions, PaymentOption::code);
    52	    }
