   111	    private List<CartLine> loadLines(List<CheckoutRequest.Item> items) {
   112	        Map<String, Product> found = products.findAllBySkus(items.stream().map(CheckoutRequest.Item::sku).toList())
   113	                .stream().collect(Collectors.toMap(Product::sku, Function.identity()));
   114	        if (items.stream().anyMatch(i -> !found.containsKey(i.sku()))) {
   115	            throw new ApiException(ErrorCode.UNKNOWN_PRODUCT);
   116	        }
   117	        if (found.values().stream().anyMatch(Product::discontinued)) {
   118	            throw new ApiException(ErrorCode.PRODUCT_DISCONTINUED);
   119	        }
   120	        if (items.stream().anyMatch(i -> found.get(i.sku()).stock() < i.quantity())) {
   121	            throw new ApiException(ErrorCode.INSUFFICIENT_STOCK);
   122	        }
   123	        return items.stream().map(i -> new CartLine(found.get(i.sku()), i.quantity())).toList();
   124	    }
